export const HISN_DUAS: HisnDua[] = [
  { id: "d1", ch: 1, arabic: "الحَمْدُ لِلّٰهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ" },
  { id: "d2", ch: 1, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، سُبْحَانَ اللّٰهِ، وَالحَمْدُ لِلّٰهِ، وَلَا إِلٰهَ إِلَّا اللّٰهُ، وَاللّٰهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ الْعَلِيِّ الْعَظِيمِ، رَبِّ اغْفِرْ لِي" },
  { id: "d3", ch: 1, arabic: "الحَمْدُ لِلّٰهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لِي بِذِكْرِهِ" },
  { id: "d4", ch: 1, arabic: "إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ {ayah:190}\nٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا سُبۡحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ {ayah:191}\nرَبَّنَآ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَيۡتَهُۥۖ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٖ {ayah:192}\nرَّبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِيٗا يُنَادِي لِلۡإِيمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ {ayah:193}\nرَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ ٱلۡقِيَٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِيعَادَ {ayah:194}\nفَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّي لَآ أُضِيعُ عَمَلَ عَٰمِلٖ مِّنكُم مِّن ذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضٖۖ فَٱلَّذِينَ هَاجَرُواْ وَأُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأُوذُواْ فِي سَبِيلِي وَقَٰتَلُواْ وَقُتِلُواْ لَأُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ ثَوَابٗا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلثَّوَابِ {ayah:195}\nلَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ فِي ٱلۡبِلَٰدِ {ayah:196}\nمَتَٰعٞ قَلِيلٞ ثُمَّ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ {ayah:197}\nلَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا نُزُلٗا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَيۡرٞ لِّلۡأَبۡرَارِ {ayah:198}\nوَإِنَّ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَمَن يُؤۡمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡكُمۡ وَمَآ أُنزِلَ إِلَيۡهِمۡ خَٰشِعِينَ لِلَّهِ لَا يَشۡتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ أُوْلَٰٓئِكَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ {ayah:199}\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ {ayah:200}" },
  { id: "d5", ch: 2, arabic: "الحَمْدُ لِلّٰهِ الَّذِي كَسَانِي هَذَا (الثَّوْبَ) وَرَزَقَنِيهِ مِنْ غَيْرِ حَولٍ مِنِّي وَلَا قُوَّةٍ" },
  { id: "d6", ch: 3, arabic: "اللّٰهُمَّ لَكَ الحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشِّرِ مَا صُنِعَ لَهُ" },
  { id: "d7", ch: 4, arabic: "تُبْلِي وَيُخْلِفُ اللّٰهُ تَعَالَى" },
  { id: "d8", ch: 4, arabic: "اِلْبَسْ جَدِيدًا، وَعِشْ حَمِيدًا، وَمُتْ شَهِيدًا" },
  { id: "d9", ch: 5, arabic: "بِسْمِ اللّٰهِ" },
  { id: "d10", ch: 6, arabic: "[بِسْمِ اللّٰهِ] اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبْثِ وَالْخَبَائِثِ" },
  { id: "d11", ch: 7, arabic: "غُفْرَانَكَ" },
  { id: "d12", ch: 8, arabic: "بِسْمِ اللّٰهِ" },
  { id: "d13", ch: 9, arabic: "أَشْهَدُ أَنْ لَّا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ" },
  { id: "d14", ch: 9, arabic: "اللّٰهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ، وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ" },
  { id: "d15", ch: 9, arabic: "سُبْحَانَكَ اللّٰهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَّا إِلٰهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ" },
  { id: "d16", ch: 10, arabic: "بِسْمِ اللّٰهِ، تَوَكَّلْتُ عَلَى اللّٰهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ" },
  { id: "d17", ch: 10, arabic: "اللّٰهُمَّ إِنَّي أَعْوْذُ بِكَ أَنْ أَضِلَّ، أَوْ أُضِلَّ، أَوْ أَزِلَّ، أُوْ أُزَلَّ أَوْ أَظْلِمَ، أَوْ أُظْلَمَ، أَوْ أَجْهَلَ، أَوْ يُجْهَلَ عَلَيَّ" },
  { id: "d18", ch: 11, arabic: "بِسْمِ اللّٰهِ وَلَجْنَا، وَبِسْمِ اللّٰهِ خَرَجْنَا، وَعَلَى اللّٰهِ رَبِّنَا تَوَكَّلْنَا" },
  { id: "d19", ch: 12, arabic: "اللّٰهُمَّ اجْعَلْ لِي نُورًا فِي قَبْرِي [اللّٰهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَفِي سَمْعِي نُورًا، وَفِي بَصَرِي نُورًا، وَمِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ شِمَالِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَمِنْ خَلْفِي نُورًا، وَاجْعَلْ فِي نَفْسِي نُورًا، وَأَعْظِمْ لِي نُورًا، وَعَظِّمْ لِي نُورًا، وَاجْعَلْ لِي نُورًا، وَاجْعَلْنِي نُورًا، اللّٰهُمَّ أَعْطِنِي نُورًا، وَاجْعَلْ فِي عَصَبِي نُورًا، وَفِي لَحْمِي نُورًا، وَفِي دَمِي نُورًا، وَفِي شَعْرِي نُورًا، وَفِي بَشَرِي نُورًا] وَنُورًا فِي عِظَامِي [وَزِدْنِي نُورًا، وَزِدْنِي نُورًا، وَزِدْنِي نُورًا] [وَهَبْ لِي نُورًا عَلَى نُورٍ]" },
  { id: "d20", ch: 13, arabic: "أَعُوذُ بِاللّٰهِ العَظِيمِ، وَبِوَجْهِهِ الكَرِيمِ، وسُلْطَانِهِ القَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ [بِسْمِ اللّٰهِ، وَالصَّلَاةُ] [وَالسَّلَامُ عَلَى رَسُولِ اللّٰهِ]، [اللّٰهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ]" },
  { id: "d21", ch: 14, arabic: "بِسْمِ اللّٰهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللّٰهِ، اللّٰهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ، اللّٰهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيْمِ" },
  { id: "d22", ch: 15, arabic: "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ" },
  { id: "d23", ch: 15, arabic: "وَأَنَا أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللّٰهِ رَبًّا، وَبِمُحَمَّدٍ رَسُولًا، وَبِالإِسْلَامِ دِينًا" },
  { id: "d25", ch: 15, arabic: "اللّٰهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلاةِ القَائِمَةِ، آتِ مُحَمَّدًا الوَسِيْلَةَ وَالفَضِيْلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُوْدًا الَّذِي وَعَدْتَهُ، [إِنَّكَ لَا تُخْلِفُ الْمِيعَادِ]" },
  { id: "d27", ch: 16, arabic: "اللّٰهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللّٰهُمَّ نَقِّنِي مِنْ خَطَايَايَ، كَمَا يُنَقَّى الثَّوْبُ الأَبْيَضُ مِنَ الدَّنَسِ، اللّٰهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ، بِالثَّلْجِ وَالْمَاءِ وَالْبَرَدِ" },
  { id: "d28", ch: 16, arabic: "سُبْحَانَكَ اللّٰهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلٰهَ غَيْرُكَ" },
  { id: "d29", ch: 16, arabic: "وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلاتِي، وَنُسُكِي، وَمَحْيَايَ، وَمَمَاتِي لِلّٰهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ، وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. اللّٰهُمَّ أَنْتَ الْمَلِكُ لَا إِلٰهَ إِلَّا أَنْتَ، أَنْتَ رَبِّي، وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي، وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، وَاهْدِنِي لِأَحْسَنِ الأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ، لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ كُلُّهُ بِيَدَيْكَ، وَالشَّرُّ لَيْسَ إِلَيْكَ، أَنَا بِكَ وَإِلَيْكَ، تَبَارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتُوْبُ إِلَيْكَ" },
  { id: "d30", ch: 16, arabic: "اللّٰهُمَّ رَبَّ جِبرَائِيْلَ، وَمِيكَائِيْلَ، وَإِسْرَافِيلَ، فَاطِرَ السَّمَوَاتِ وَالأرْضِ، عَالِمَ الغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُواْ فِيهِ يَخْتَلِفُونَ، اِهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الحَقِّ بِإِذْنِكَ، إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ" },
  { id: "d31", ch: 16, arabic: "اللّٰهُ أَكْبَرُ كَبِيرًا، اللّٰهُ أَكْبَرُ كَبِيرًا، اللّٰهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلّٰهِ كَثِيرًا، وَالْحَمْدُ لِلّٰهِ كَثِيرًا، وَالْحَمْدُ لِلّٰهِ كَثِيرًا، وَسُبْحَانَ اللّٰهِ بُكْرَةً وَأَصِيلًا\nأَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ، مِنْ نَفْحِهِ وَنَفْثِهِ وَ هَمْزِهِ" },
  { id: "d32", ch: 16, arabic: "اللّٰهُمَّ لَكَ الحَمْدُ أَنْتَ نُورُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الحَمْدُ أَنْتَ قَيِّمُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، [وَلَكَ الحَمْدُ أَنْتَ رَبُّ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ]، [وَلَكَ الحَمْدُ لَكَ مُلْكُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ] [وَلَكَ الحَمْدُ أَنْتَ مَلِكُ السَّمَوَاتِ وَالأَرْضِ] [وَلَكَ الحَمْدُ] [أَنْتَ الحَقُّ، وَوَعْدُكَ الحَقُّ، وَقَوْلُكَ الحَقُّ، وَلِقَاؤُكَ الحَقُّ، وَالجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمُحَمَّدٌ - {SAW} - حَقٌّ، وَالسَّاعَةُ حَقٌّ] [اللّٰهُمَّ لَكَ أَسْلَمْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَبِكَ آمَنْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ، فَاغْفِرْ لِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ] [أَنْتَ المُقَدِّمُ، وَأَنْتَ المُؤَخِّرُ لَا إِلٰهَ إِلَّا أَنْتَ] [أَنْتَ إِلٰهِي لَا إِلٰهَ إِلَّا أَنْتَ]" },
  { id: "d33", ch: 17, arabic: "سُبْحَانَ رَبِّيَ الْعَظِيمِ" },
  { id: "d34", ch: 17, arabic: "سُبْحَانَكَ اللّٰهُمَّ رَبَّنَا وَبِحَمْدِكَ اللّٰهُمَّ اغْفِرْ لِي" },
  { id: "d35", ch: 17, arabic: "سُبُّوحٌ، قُدُّوسٌ، رَبُّ المَلائِكَةِ وَالرُّوحِ" },
  { id: "d36", ch: 17, arabic: "اللّٰهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي، وَبَصَرِي، وَمُخِّي، وَعَظْمِي، وَعَصَبِي، [وَمَا اسْتَقَلَّتْ بِهِ قَدَمِي]" },
  { id: "d37", ch: 17, arabic: "سُبْحَانَ ذِي الْجَبَرُوتِ، وَالْمَلَكُوتِ، وَالكِبْرِيَاءِ، وَالْعَظَمَةِ" },
  { id: "d38", ch: 18, arabic: "سَمِعَ اللّٰهُ لِمَنْ حَمِدَهُ" },
  { id: "d39", ch: 18, arabic: "رَبَّنَا وَلَكَ الْحَمْدُ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ" },
  { id: "d40", ch: 18, arabic: "مِلْءَ السَّمَوَاتِ وَمِلءَ الأَرْضِ وَمَا بَيْنَهُمَا، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، أَهْلَ الثَّنَاءِ وَالمَجْدِ، أَحَقُّ مَا قَالَ العَبْدُ، وَكُلُّنَا لَكَ عَبْدٌ، اللّٰهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِي لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الجَدِّ مِنْكَ الجَدُّ" },
  { id: "d41", ch: 19, arabic: "سُبْحَانَ رَبِّيَ الأَعْلَى" },
  { id: "d42", ch: 19, arabic: "سُبْحَانَكَ اللّٰهُمَّ رَبَّنَا وَبِحَمْدِكَ اللّٰهُمَّ اغْفِرْ لِي" },
  { id: "d43", ch: 19, arabic: "سُبُّوحٌ، قُدُّوسٌ، رَبُّ المَلائِكَةِ وَالرُّوحِ" },
  { id: "d44", ch: 19, arabic: "اللّٰهُمَّ لَكَ سَجَدْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ، وَصَوَّرَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللّٰهُ أَحْسَنُ الخَالِقِينَ" },
  { id: "d45", ch: 19, arabic: "سُبْحَانَ ذِي الْجَبَرُوتِ، وَالْمَلَكُوتِ، وَالكِبْرِيَاءِ، وَالْعَظَمَةِ" },
  { id: "d46", ch: 19, arabic: "اللّٰهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ" },
  { id: "d47", ch: 19, arabic: "اللّٰهُمَّ إِنِّي أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوْذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ" },
  { id: "d48", ch: 20, arabic: "رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي" },
  { id: "d49", ch: 20, arabic: "اللّٰهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَاجْبُرْنِي، وَعَافِنِي، وَارْزُقْنِي، وَارْفَعْنِي" },
  { id: "d50", ch: 21, arabic: "سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، بِحَوْلِهِ وَقُوَّتِهِ [فَتَبَارَكَ اللّٰهُ أَحْسَنُ الْخَالِقِينَ]" },
  { id: "d51", ch: 21, arabic: "اللّٰهُمَّ اكْتُبْ لِي بِهَا عِنْدَكَ أَجْرًا، وَضَعْ عَنِّي بِهَا وِزْرًا، وَاجْعَلْهَا لِي عِنْدَكَ ذُخْرًا، وَتَقَبَّلَهَا مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ" },
  { id: "d52", ch: 22, arabic: "التَّحِيَّاتُ لِلّٰهِ، وَالصَّلَوَاتُ، وَالطَّيِّبَاتُ، السَّلامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللّٰهِ وَبَرَكَاتُهُ، السَّلامُ عَلَيْنَا وَعَلَى عِبَادِ اللّٰهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللّٰهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ" },
  { id: "d53", ch: 23, arabic: "اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللّٰهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ" },
  { id: "d54", ch: 23, arabic: "اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى أَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ، وَبَارِكْ عَلَى مُحَمَّدٍ، وَعَلَى أَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ" },
  { id: "d55", ch: 24, arabic: "اللّٰهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ جَهَنَّمَ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ" },
  { id: "d56", ch: 24, arabic: "اللّٰهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، اللّٰهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ" },
  { id: "d57", ch: 24, arabic: "اللّٰهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ" },
  { id: "d58", ch: 24, arabic: "اللّٰهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ لَا إِلٰهَ إِلَّا أَنْتَ" },
  { id: "d59", ch: 24, arabic: "اللّٰهُمَّ أَعِنِّي عَلَى ذِكْرِكَ، وَشُكْرِكَ، وَحُسْنِ عِبَادَتِكَ" },
  { id: "d60", ch: 24, arabic: "اللّٰهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ البُخْلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوْذُ بِكَ مِنْ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمْرِ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ" },
  { id: "d61", ch: 24, arabic: "اللّٰهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ، وَأَعُوْذُ بِكَ مِنَ النَّارِ" },
  { id: "d62", ch: 24, arabic: "اللّٰهُمَّ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ؛ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي، اللّٰهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْغِنَى وَالْفَقْرِ، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ، وَلَا فِتْنَةٍ مُضِلَّةٍ، اللّٰهُمَّ زَيَّنَّا بِزِينَةِ الإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ" },
  { id: "d63", ch: 24, arabic: "اللّٰهُمَّ إِنِّي أَسْأَلُكَ يَا اللّٰهُ بِأَنَّكَ الْوَاحِدُ الأَحَدُ الصَّمَدُ، الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ، أَنْ تَغْفِرَ لِي ذُنُوبِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ" },
  { id: "d64", ch: 24, arabic: "اللّٰهُمَّ إِنِّي أَسأَلُكَ بِأَنَّ لَكَ الْحَمْدُ، لَا إِلٰهَ إِلَّا أَنْتَ، وَحْدَكَ لَا شَرِيكَ لَكَ، الْمَنَّانُ، يَا بَدِيْعَ السَّمَوَاتِ وَالأَرْضِ، يَا ذَا الْجَلالِ وَالإكْرَامِ، يَا حَيُّ يَا قَيُّومُ، إِنِّي أَسْأَلُكَ الْجَنَّةَ، وَأَعُوْذُ بِكَ مِنَ النَّارِ" },
  { id: "d65", ch: 24, arabic: "اللّٰهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللّٰهُ لَا إِلٰهَ إِلَّا أَنْتَ، الأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ" },
  { id: "d66", ch: 25, arabic: "أَسْتَغْفِرُ اللّٰهَ\nاللّٰهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الجَلَالِ وَالإِكْرَامِ" },
  { id: "d67", ch: 25, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ\nاللّٰهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الجَدِّ مِنْكَ الجَدُّ" },
  { id: "d68", ch: 25, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيءٍ قَديرٌ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ، لَا إِلٰهَ إِلَّا اللّٰهُ، وَلَا نَعْبُدُ إِلَّا إِيَّاهُ، لَهُ النِّعْمَةُ وَلَهُ الفَضْلُ وَلَهُ الثَّنَاءُ الحَسَنُ، لَا إِلٰهَ إِلَّا اللّٰهُ مُخلِصِينَ لَهُ الدِّيْنَ وَلَوْ كَرِهَ الكَافِرُونَ" },
  { id: "d69", ch: 25, arabic: "سُبْحَانَ اللّٰهِ، وَالحَمْدُ لِلّٰهِ، وَاللّٰهُ أَكْبَرُ\nلَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ" },
  { id: "d70", ch: 25, arabic: "{BASMALA} قُلۡ هُوَ ٱللَّهُ أَحَدٌ {ayah:1} ٱللَّهُ ٱلصَّمَدُ {ayah:2} لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ {ayah:3} وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ {ayah:4}\n{BASMALA} قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ {ayah:1} مِن شَرِّ مَا خَلَقَ {ayah:2} وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ {ayah:3} وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِي ٱلۡعُقَدِ {ayah:4} وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ {ayah:5}\n{BASMALA} قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ {ayah:1} مَلِكِ ٱلنَّاسِ {ayah:2} إِلَٰهِ ٱلنَّاسِ {ayah:3} مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ {ayah:4} ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ {ayah:5} مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ {ayah:6}" },
  { id: "d71", ch: 25, arabic: "﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ {ayah:255}﴾" },
  { id: "d72", ch: 25, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ وَلَهُ الحَمْدُ، يُحيِي وَيُمِيتُ، وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ" },
  { id: "d73", ch: 25, arabic: "اللّٰهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا" },
  { id: "d74", ch: 26, arabic: "«اللّٰهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ العَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الغُيُوبِ، اللّٰهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ (وَيُسَمِّي حَاجَتَهُ) خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي (أَوْ قَالَ: [عَاجِلِهِ وَآجِلِهِ]) فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي، ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي (أَوْ قَالَ: [عَاجِلِهِ وَآجِلِهِ]) فَاصْرِفْهُ عَنِّي، وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي بِهِ»" },
  { id: "d75", ch: 27, arabic: "﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ {ayah:255} ﴾" },
  { id: "d76", ch: 27, arabic: "{BASMALA} قُلۡ هُوَ ٱللَّهُ أَحَدٌ {ayah:1} ٱللَّهُ ٱلصَّمَدُ {ayah:2} لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ {ayah:3} وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ {ayah:4}\n{BASMALA} قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ {ayah:1} مِن شَرِّ مَا خَلَقَ {ayah:2} وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ {ayah:3} وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِي ٱلۡعُقَدِ {ayah:4} وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ {ayah:5}\n{BASMALA} قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ {ayah:1} مَلِكِ ٱلنَّاسِ {ayah:2} إِلَٰهِ ٱلنَّاسِ {ayah:3} مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ {ayah:4} ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ {ayah:5} مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ {ayah:6}" },
  { id: "d77", ch: 27, arabic: "أَصْبَحْنَا وَأَصْبَحَ المُلْكُ لِلّٰهِ، وَالحَمْدُ لِلّٰهِ، لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَريكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا اليَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا اليَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الكَسَلِ، وَسُوءِ الكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي القَبْرِ\nأَمْسَيْنَا وَأَمْسَى المُلْكُ لِلّٰهِ، وَالحَمْدُ لِلّٰهِ، لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَريْكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ الكَسَلِ، وَسُوءِ الكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي القَبْرِ" },
  { id: "d78", ch: 27, arabic: "اللّٰهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ\nاللّٰهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوْتُ، وَإِلَيْكَ المَصِيْرُ" },
  { id: "d79", ch: 27, arabic: "اللّٰهُمَّ أَنْتَ رَبِّي لَا إلٰهَ إلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوْءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوْءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ" },
  { id: "d80", ch: 27, arabic: "اللّٰهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلائِكَتَكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللّٰهُ لَا إِلٰهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيْكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ\nاللّٰهُمَّ إِنِّي أَمْسَيْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلائِكَتَكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللّٰهُ لَا إِلٰهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيْكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ" },
  { id: "d81", ch: 27, arabic: "اللّٰهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ، أَوْ بِأَحَدٍ مِنْ خَلْقِكَ، فَمِنْكَ وَحْدَكَ لَا شَرِيْكَ لَكَ، فَلَكَ الحَمْدُ وَلَكَ الشُّكْرُ\nاللّٰهُمَّ مَا أَمْسَى بِي مِنْ نِعْمَةٍ، أَوْ بِأَحَدٍ مِنْ خَلْقِكَ، فَمِنْكَ وَحْدَكَ لَا شَرِيْكَ لَكَ، فَلَكَ الحَمْدُ وَلَكَ الشُّكْرُ" },
  { id: "d82", ch: 27, arabic: "اللّٰهُمَّ عَافِنِي فِي بَدَنِي، اللّٰهُمَّ عَافِنِي فِي سَمْعِي، اللّٰهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلٰهَ إِلَّا أَنْتَ، اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الكُفْرِ وَالفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ القَبْرِ، لَا إلٰهَ إلَّا أَنْتَ" },
  { id: "d83", ch: 27, arabic: "حَسْبِيَ اللّٰهُ لَا إلٰهَ إلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ العَرْشِ العَظِيمِ" },
  { id: "d84", ch: 27, arabic: "اللّٰهُمَّ إِنِّي أَسْأَلُكَ العَفْوَ وَالعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ، اللّٰهُمَّ إِنِّي أَسْأَلُكَ العَفْوَ وَالعَافِيَةَ فِي دِيْنِي وَدُنْيَايَ، وَأَهْلِي، وَمَالِي، اللّٰهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللّٰهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي" },
  { id: "d85", ch: 27, arabic: "اللّٰهُمَّ عَالِمَ الغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَوَاتِ وَالأَرْضِ، رَبَّ كُلِّ شَيءٍ ومَلِيْكَهُ، أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ" },
  { id: "d86", ch: 27, arabic: "بِسْمِ اللّٰهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيءٌ فِي الأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ العَلِيْمُ" },
  { id: "d87", ch: 27, arabic: "رَضِيْتُ بِاللّٰهِ رَبًّا، وَبِالإِسْلَامِ دِيْنًا، وبِمُحَمَّدٍ نَبِيًّا" },
  { id: "d88", ch: 27, arabic: "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ" },
  { id: "d89", ch: 27, arabic: "أَصْبَحْنَا وَأَصْبَحَ المُلْكُ لِلّٰهِ رَبِّ العَالَمِيْنَ، اللّٰهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا اليَوْمِ: فَتْحَهُ، وَنَصْرَهُ، وَنُورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِيْهِ وَشَرِّ مَا بَعْدَهُ\nأَمْسَيْنَا وَأَمْسَى المُلْكُ لِلّٰهِ رَبِّ العَالَمِيْنَ، اللّٰهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذِهِ اللَّيْلَةِ: فَتْحَهَا، وَنَصْرَهَا، وَنُورَهَا، وَبَرَكَتَهَا، وَهُدَاهَا، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِيْهَا وَشَرِّ مَا بَعْدَهَا" },
  { id: "d90", ch: 27, arabic: "أَصْبَحْنَا عَلَى فِطْرَةِ الإِسْلَامِ، وَعَلَى كَلِمَةِ الإِخْلَاصِ، وَعَلَى دِيْنِ نَبِيِّنَا مُحَمَّدٍ {SAW} وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ المُشْرِكِينَ\nأَمْسَيْنَا عَلَى فِطْرَةِ الإِسْلَامِ، وَعَلَى كَلِمَةِ الإِخْلَاصِ، وَعَلَى دِيْنِ نَبِيِّنَا مُحَمَّدٍ {SAW} وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ المُشْرِكِينَ" },
  { id: "d91", ch: 27, arabic: "سُبْحَانَ اللّٰهِ وَبِحَمْدِهِ" },
  { id: "d92", ch: 27, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ" },
  { id: "d93", ch: 27, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ، وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ المُلْكُ وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ" },
  { id: "d94", ch: 27, arabic: "سُبْحَانَ اللّٰهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ" },
  { id: "d95", ch: 27, arabic: "اللّٰهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا" },
  { id: "d96", ch: 27, arabic: "أَسْتَغْفِرُ اللّٰهَ وَأَتُوبُ إِلَيْهِ" },
  { id: "d97", ch: 27, arabic: "أَعُوْذُ بِكَلِمَاتِ اللّٰهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ" },
  { id: "d98", ch: 27, arabic: "اللّٰهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ" },
  { id: "d99", ch: 28, arabic: "{BASMALA} قُلۡ هُوَ ٱللَّهُ أَحَدٌ {ayah:1} ٱللَّهُ ٱلصَّمَدُ {ayah:2} لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ {ayah:3} وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ {ayah:4}\n{BASMALA} قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ {ayah:1} مِن شَرِّ مَا خَلَقَ {ayah:2} وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ {ayah:3} وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِي ٱلۡعُقَدِ {ayah:4} وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ {ayah:5}\n{BASMALA} قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ {ayah:1} مَلِكِ ٱلنَّاسِ {ayah:2} إِلَٰهِ ٱلنَّاسِ {ayah:3} مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ {ayah:4} ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ {ayah:5} مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ {ayah:6}" },
  { id: "d100", ch: 28, arabic: "﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ {ayah:255}﴾" },
  { id: "d101", ch: 28, arabic: "﴿ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ وَقَالُواْ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ {ayah:285} لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ {ayah:286}﴾" },
  { id: "d102", ch: 28, arabic: "بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ" },
  { id: "d103", ch: 28, arabic: "اللّٰهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا، اللّٰهُمَّ إِنِّي أَسْأَلُكَ العَافِيَةَ" },
  { id: "d104", ch: 28, arabic: "اللّٰهُمَّ قِنِي عَذَابَكَ، يَوْمَ تَبْعَثُ عِبَادَكَ" },
  { id: "d105", ch: 28, arabic: "بِاسْمِكَ اللّٰهُمَّ أَمُوتُ وَأَحْيَا" },
  { id: "d106", ch: 28, arabic: "سُبْحَانَ اللّٰهِ\nالحَمْدُ لِلّٰهِ\nاللّٰهُ أَكْبَرُ" },
  { id: "d107", ch: 28, arabic: "اللّٰهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ، وَرَبَّ الأَرْضِ، وَرَبَّ العَرْشِ العَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيءٍ، فَالِقَ الحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالإِنْجِيلِ وَالفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، اللّٰهُمَّ أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ البَاطِنُ فَلَيْسَ دُونَكَ شَيءٌ، اِقْضِ عَنَّا الدَّيْنَ، وَأَغْنِنَا مِنَ الفَقْرِ" },
  { id: "d108", ch: 28, arabic: "الحَمْدُ لِلّٰهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا؛ فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ" },
  { id: "d109", ch: 28, arabic: "اللّٰهُمَّ عَالِمَ الغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَوَاتِ وَالأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيْكَهُ، أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا أَنْتَ، أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ" },
  { id: "d111", ch: 28, arabic: "اللّٰهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ" },
  { id: "d112", ch: 29, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ الوَاحِدُ القَهَّارُ، رَبُّ السَّمَوَاتِ وَالأَرْضِ وَمَا بَيْنَهُمَا العَزِيْزُ الغَفَّارُ" },
  { id: "d113", ch: 30, arabic: "أَعُوذُ بِكَلِمَاتِ اللّٰهِ التَّامَّاتِ، مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ، وَأَنْ يَحْضُرُونِ" },
  { id: "d114", ch: 31, arabic: "أَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ..." },
  { id: "d116", ch: 32, arabic: "اللّٰهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، [وَلَا يَعِزُّ مَنْ عَادَيْتَ]، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ" },
  { id: "d117", ch: 32, arabic: "اللّٰهُمَّ إِنِّي أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوْذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ" },
  { id: "d118", ch: 32, arabic: "اللّٰهُمَّ إِيَّاكَ نَعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَى وَنَحْفِدُ، نَرْجُو رَحْمَتَكَ، وَنَخْشَى عَذَابَك، إِنَّ عَذَابَكَ بِالكَافِرِيْنَ مُلْحَقٌ، اللّٰهُمَّ إِنَّا نَسْتَعِينُكَ، ونَسْتَغْفِرُكَ، وَنُثْنِي عَلَيْكَ الخَيْرَ، وَلَا نَكْفُرُكَ، وَنُؤْمِنُ بِكَ، وَنَخْضَعُ لَكَ، وَنَخْلَعُ مَنْ يَكْفُرُكَ" },
  { id: "d119", ch: 33, arabic: "سُبْحَانَ المَلِكِ القُدُّوسِ\nرَبِّ المَلَائِكَةِ وَالرُّوحِ" },
  { id: "d120", ch: 34, arabic: "اللّٰهُمَّ إِنِّي عَبْدُكَ، اِبْنُ عَبدِكَ، اِبْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ القُرْآنَ رَبِيْعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلَاءَ حُزْنِي، وَذَهَابَ هَمِّي" },
  { id: "d121", ch: 34, arabic: "اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الهَمِّ وَالحَزَنِ، وَالعَجْزِ وَالكَسَلِ، وَالبُخْلِ وَالجُبْنِ، وضَلَعِ الدَّيْنِ وغَلَبَةِ الرِّجَالِ" },
  { id: "d122", ch: 35, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ العَظِيمُ الحَلِيمُ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ العَرْشِ العَظِيمِ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ السَّمَوَاتِ، وَرَبُّ الأَرْضِ وَرَبُّ العَرْشِ الكَريْمِ" },
  { id: "d123", ch: 35, arabic: "اللّٰهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلٰهَ إِلَّا أَنْتَ" },
  { id: "d124", ch: 35, arabic: "لَا إِلٰهَ إِلَّا أَنْتَ سُبْحَانَكَ، إِنِّي كُنْتُ مِنَ الظَّالِمينَ" },
  { id: "d125", ch: 35, arabic: "اللّٰهُ اللّٰهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا" },
  { id: "d126", ch: 36, arabic: "اللّٰهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُوْرِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ" },
  { id: "d127", ch: 36, arabic: "اللّٰهُمَّ أَنْتَ عَضُدِي، وَأَنْتَ نَصِيرِي، بِكَ أَحُولُ، وَبِكَ أَصُولُ، وَبِكَ أُقَاتِلُ" },
  { id: "d128", ch: 36, arabic: "حَسْبُنَا اللّٰهُ، ونِعْمَ الوَكِيلُ" },
  { id: "d129", ch: 37, arabic: "اللّٰهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ، وَرَبَّ العَرْشِ العَظِيمِ، كُنْ لِي جَارًا مِنْ [فُلَانِ بْنِ فُلانٍ]، وَأَحْزَابِهِ مِنْ خَلائِقِكَ؛ أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ يَطْغَى، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ، وَلَا إِلٰهَ إِلَّا أَنْتَ" },
  { id: "d130", ch: 37, arabic: "اللّٰهُ أَكْبَرُ، اللّٰهُ أَعَزُّ مِنْ خَلْقِهِ جَمِيعًا، اللّٰهُ أَعَزُّ مِمَّا أَخَافُ وَأَحْذَرُ، أَعُوذُ بِاللّٰهِ الَّذِي لَا إِلٰهَ إِلَّا هُوَ، المُمْسِكِ السَّمَوَاتِ السَّبْعِ أَنْ يَقَعْنَ عَلَى الأَرْضِ إِلَّا بِإِذْنِهِ، مِنْ شَرِّ عَبْدِكَ [فُلانٍ]، وُجُنُودِهِ وَأَتْبَاعِهِ وَأَشْيَاعِهِ، مِنَ الجِنِّ وَالإِنْسِ، اللّٰهُمَّ كُنْ لِي جَارًا مِنْ شَرِّهِمْ، جَلَّ ثَنَاؤُكَ، وَعَزَّ جَارُكَ، وَتَبَارَكَ اسْمُكَ: وَلَا إِلٰهَ غَيْرُكَ" },
  { id: "d131", ch: 38, arabic: "اللّٰهُمَّ مُنْزِلَ الكِتَابِ، سَرِيْعَ الحِسَابِ، اِهْزِمِ الأَحْزَابَ، اللّٰهُمَّ اهْزِمْهُمْ وزَلْزِلْهُمْ" },
  { id: "d132", ch: 39, arabic: "اللّٰهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ" },
  { id: "d133", ch: 40, arabic: "أَعُوذُ بِاللّٰهِ" },
  { id: "d134", ch: 40, arabic: "آمَنْتُ بِاللّٰهِ وَرُسُلِهِ" },
  { id: "d135", ch: 40, arabic: "﴿هُوَ ٱلۡأَوَّلُ وَٱلۡأٓخِرُ وَٱلظَّٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٌ {ayah:3}﴾" },
  { id: "d136", ch: 41, arabic: "اللّٰهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ" },
  { id: "d137", ch: 41, arabic: "اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الهَمِّ وَالحَزَنِ، وَالعَجْزِ وَالكَسَلِ، وَالبُخْلِ وَالجُبْنِ، وَضَلْعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ" },
  { id: "d138", ch: 42, arabic: "أَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ" },
  { id: "d139", ch: 43, arabic: "اللّٰهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الحَزْنَ إِذَا شِئْتَ سَهْلًا" },
  { id: "d141", ch: 45, arabic: "أَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ" },
  { id: "d144", ch: 46, arabic: "قَدَرُ اللّٰهِ وَمَا شَاءَ فَعَلَ" },
  { id: "d145", ch: 47, arabic: "بَارَكَ اللّٰهُ لَكَ فِي المَوْهُوبِ لَكَ، وَشَكَرْتَ الوَاهِبَ، وبَلَغَ أَشُدَّهُ، وَرُزِقْتَ بِرَّهُ\nبَارَكَ اللّٰهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَزَاكَ اللّٰهُ خَيْرًا، وَرَزَقَكَ اللّٰهُ مِثْلَهُ، وَأَجْزَلَ ثَوَابَكَ" },
  { id: "d146", ch: 48, arabic: "أُعِيذُكُمَا بِكَلِمَاتِ اللّٰهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ" },
  { id: "d147", ch: 49, arabic: "لا بَأْسَ طَهُورٌ إنْ شَاءَ اللّٰهُ" },
  { id: "d148", ch: 49, arabic: "أَسَأَلُ اللّٰهَ العَظِيمَ، رَبَّ العَرْشِ العَظِيمِ، أَنْ يَشْفِيَكَ" },
  { id: "d150", ch: 51, arabic: "اللّٰهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَأَلْحِقْنِي بِالرَّفِيقِ الأَعْلَى" },
  { id: "d151", ch: 51, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ إِنَّ لِلْمَوْتِ سَكَرَاتٍ" },
  { id: "d152", ch: 51, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ وَاللّٰهُ أَكْبَرُ، لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ، لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَا إِلٰهَ إِلَّا اللّٰهُ لَهُ المُلْكُ وَلَهُ الحَمْدُ، لَا إِلٰهَ إِلَّا اللّٰهُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ" },
  { id: "d153", ch: 52, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ" },
  { id: "d154", ch: 53, arabic: "إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللّٰهُمَّ أْجُرْنِي فِي مُصِيْبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا" },
  { id: "d155", ch: 54, arabic: "اللّٰهُمَّ اغْفِرْ لِ[فُلَانٍ بِاسْمِهِ]، وَارْفَعْ دَرَجَتَهُ فِي المَهْدِيِّيْنَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الغَابِرِيْنَ، وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ العَالَمِيْنَ، وَافْسَحْ لَهُ فِي قَبْرِهِ وَنَوِّرْ لَهُ فِيْهِ" },
  { id: "d156", ch: 55, arabic: "اللّٰهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ، وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلهُ بِالمَاءِ وَالثَّلْجِ وَالبَرَدِ، وَنَقِّهِ مِنَ الخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَأَدْخِلْهُ الجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ القَبْرِ [وَعَذَابِ النَّارِ]" },
  { id: "d157", ch: 55, arabic: "اللّٰهُمَّ اغْفِرْ لِحَيِّنَا، وَمَيِّتِنَا، وَشَاهِدِنَا، وَغَائِبِنَا، وَصَغِيْرِنَا، وَكَبِيرِنَا، وَذَكَرِنَا، وَأُنْثَانَا، اللّٰهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الإِسْلَامِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الإِيْمَانِ، اللّٰهُمَّ لَا تَحْرِمْنَا أَجْرَهُ، وَلَا تُضِلَّنَا بَعْدَهُ" },
  { id: "d158", ch: 55, arabic: "اللّٰهُمَّ إِنَّ [فُلَانَ بْنَ فُلانٍ] فِي ذِمَّتِكَ، وَحَبْلِ جِوَارِكَ، فَقِهِ مِنْ فِتْنَةِ القَبْرِ وَعَذَابِ النَّارِ، وَأَنْتَ أَهْلُ الوَفَاءِ وَالحَقِّ، فَاغْفِرْ لَهُ، وَارْحَمْهُ، إِنَّكَ أَنْتَ الغَفُورُ الرَّحِيمُ" },
  { id: "d159", ch: 55, arabic: "اللّٰهُمَّ عَبْدُكَ وَابْنُ أَمَتِكَ، اِحْتَاجَ إِلَى رَحْمَتِكَ، وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهِ، إِنْ كَانَ مُحْسِنًا فَزِدْ فِي حَسَنَاتِهِ، وَإِنْ كَانَ مُسِيئًا فَتَجَاوَزْ عَنْهُ" },
  { id: "d160", ch: 56, arabic: "اللّٰهُمَّ أَعِذْهُ مِنْ عَذَابِ القَبْرِ\nاللّٰهُمَّ اجْعَلْهُ فَرَطًا وَذُخْرًا لِوَالِدَيْهِ، وَشَفِيعًا مُجَابًا، اللّٰهُمَّ ثَقِّلْ بِهِ مَوَازِيْنَهُمَا، وَأَعْظِمْ بِهِ أُجُورَهُمَا، وَأَلْحِقْهُ بِصَالِحِ المُؤْمِنِينَ، وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ، وَقِهِ بِرَحْمَتِكَ عَذَابَ الجَحِيمِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، اللّٰهُمَّ اغْفِرْ لِأَسْلَافِنَا، وَأَفْرَاطِنَا، وَمَنْ سَبَقَنَا بِالإِيْمَانِ" },
  { id: "d161", ch: 56, arabic: "اللّٰهُمَّ اجْعَلْهُ لَنَا فَرَطًا، وَسَلَفًا، وَأَجْرًا" },
  { id: "d162", ch: 57, arabic: "إِنَّ لِلّٰهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَى، وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمّىً، فَلْتَصْبِرْ وَلْتَحْتَسِبْ\nأَعْظَمَ اللّٰهُ أَجْرَكَ، وَأَحْسَنَ عَزَاءَكَ، وَغَفَرَ لِمَيِّتِكَ" },
  { id: "d163", ch: 58, arabic: "بِسْمِ اللّٰهِ، وَعَلَى سُنَّةِ رَسُولِ اللّٰهِ" },
  { id: "d164", ch: 59, arabic: "اللّٰهُمَّ اغْفِرْ لَهُ، اللّٰهُمَّ ثَبِّتْهُ" },
  { id: "d165", ch: 60, arabic: "السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ المُؤْمِنِينَ وَالمُسْلِمِينَ، وَإنَّا إنْ شَاءَ اللّٰهُ بِكُمْ لَاحِقُونَ، [وَيَرْحَمُ اللّٰهُ المُستَقْدِمِينَ مِنَّا وَالمُسْتَأْخِرِينَ] أَسْأَلُ اللّٰهَ لَنَا وَلَكُمُ العَافِيَةَ" },
  { id: "d166", ch: 61, arabic: "اللّٰهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا" },
  { id: "d167", ch: 61, arabic: "اللّٰهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيْهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيْهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ" },
  { id: "d168", ch: 62, arabic: "سُبْحَانَ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ، وَالمَلَائِكَةُ مِنْ خِيْفَتِهِ" },
  { id: "d169", ch: 63, arabic: "اللّٰهُمَّ أَسْقِنَا غَيْثًا مُغِيثًا مَرِيئًا مَرِيعًا، نَافِعًا، غَيْرَ ضَارٍّ، عَاجِلًا غَيْرَ آجِلٍ" },
  { id: "d170", ch: 63, arabic: "اللّٰهُمَّ أَغِثْنَا، اللّٰهُمَّ أَغِثْنَا، اللّٰهُمَّ أَغِثْنَا" },
  { id: "d171", ch: 63, arabic: "اللّٰهُمَّ اسْقِ عِبَادَكَ، وَبَهَائِمَكَ، وَانْشُرْ رَحْمَتَكَ، وَأَحْيِ بَلَدَكَ المَيِّتَ" },
  { id: "d172", ch: 64, arabic: "اللّٰهُمَّ صَيِّبًا نَافِعًا" },
  { id: "d173", ch: 65, arabic: "مُطِرْنَا بِفَضْلِ اللّٰهِ وَرَحْمَتِهِ" },
  { id: "d174", ch: 66, arabic: "اللّٰهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا، اللّٰهُمَّ عَلَى الآكَامِ وَالظِّرَابِ، وَبُطُونِ الأَوْدِيَةِ، وَمَنَابِتِ الشَّجَرِ" },
  { id: "d175", ch: 67, arabic: "اللّٰهُ أَكْبَرُ، اللّٰهُمَّ أَهِلَّهُ عَلَيْنَا بِالْأَمْنِ وَالإِيْمَانِ، وَالسَّلَامَةِ وَالإِسْلَامِ، وَالتَّوْفِيْقِ لِمَا تُحِبُّ رَبَّنَا وَتَرْضَى، رَبُّنَا وَرَبُّكَ اللّٰهُ" },
  { id: "d176", ch: 68, arabic: "ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ العُرُوقُ، وَثَبَتَ الأَجْرُ إِنْ شَاءَ اللّٰهُ" },
  { id: "d177", ch: 68, arabic: "اللّٰهُمَّ إِنِّي أَسْأَلُكَ بِرَحْمَتِكَ الَّتِي وَسِعَتْ كُلَّ شَيْءٍ، أَنْ تَغْفِرَ لِي" },
  { id: "d178", ch: 69, arabic: "بِسْمِ اللّٰهِ\nبِسْمِ اللّٰهِ فِي أَوَّلِهِ وَآخِرِهِ" },
  { id: "d179", ch: 69, arabic: "اللّٰهُمَّ بَارِكْ لَنَا فِيْهِ، وَأَطْعِمْنَا خَيْرًا مِنْهُ\nاللّٰهُمَّ بَارِكْ لَنَا فِيْهِ، وَزِدْنَا مِنْهُ" },
  { id: "d180", ch: 70, arabic: "الحَمْدُ لِلّٰهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ" },
  { id: "d181", ch: 70, arabic: "الحَمْدُ لِلّٰهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ [مَكْفِيٍّ وَلَا] مُوَدَّعٍ، وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا" },
  { id: "d182", ch: 71, arabic: "اللّٰهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ، وَارْحَمْهُمْ" },
  { id: "d183", ch: 72, arabic: "اللّٰهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِي، وَاسْقِ مَنْ سَقَانِي" },
  { id: "d184", ch: 73, arabic: "أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ المَلَائِكَةُ" },
  { id: "d186", ch: 75, arabic: "إِنِّي صَائِمٌ، إِنِّي صَائِمٌ" },
  { id: "d187", ch: 76, arabic: "اللّٰهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا، وَبَارِكْ لَنَا فِي مَدِيْنَتِنَا، وَبَارِكْ لَنَا فِي صَاعِنَا، وَبَارِكْ لَنَا فِي مُدِّنَا" },
  { id: "d188", ch: 77, arabic: "الحَمْدُ لِلّٰهِ\nيَرْحَمُكَ اللّٰهُ\nيَهْدِيكُمُ اللّٰهُ، وَيُصْلِحُ بَالَكُمْ" },
  { id: "d189", ch: 78, arabic: "يَهْدِيكُمُ اللّٰهُ، وَيُصْلِحُ بَالَكُمْ" },
  { id: "d190", ch: 79, arabic: "بَارَكَ اللّٰهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ" },
  { id: "d191", ch: 80, arabic: "اللّٰهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوْذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ" },
  { id: "d192", ch: 81, arabic: "بِسْمِ اللّٰهِ، اللّٰهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا" },
  { id: "d193", ch: 82, arabic: "أَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ" },
  { id: "d194", ch: 83, arabic: "الحَمْدُ لِلّٰهِ الَّذِي عَافَانِي مِمَّا ابْتَلَاكَ بِهِ، وَفَضَّلَنِي عَلَى كَثيرٍ مِمَّنْ خَلَقَ تَفْضِيلًا" },
  { id: "d195", ch: 84, arabic: "رَبِّ اغْفِرْ لِي، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الغَفُورُ" },
  { id: "d196", ch: 85, arabic: "سُبْحَانَكَ اللّٰهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ" },
  { id: "d197", ch: 86, arabic: "وَلَكَ" },
  { id: "d198", ch: 87, arabic: "جَزَاكَ اللّٰهُ خَيْرًا" },
  { id: "d200", ch: 89, arabic: "أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ" },
  { id: "d201", ch: 90, arabic: "بَارَكَ اللّٰهُ لَكَ فِي أَهْلِكَ وَمَالِكَ" },
  { id: "d202", ch: 91, arabic: "بَارَكَ اللّٰهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، إِنَّمَا جَزَاءُ السَّلَفِ الحَمْدُ وَالأَدَاءُ" },
  { id: "d203", ch: 92, arabic: "اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ" },
  { id: "d204", ch: 93, arabic: "وَفِيكَ بَارَكَ اللّٰهُ" },
  { id: "d205", ch: 94, arabic: "اللّٰهُمَّ لَا طَيْرَ إِلَّا طَيْرُكَ، وَلَا خَيْرَ إِلَّا خَيْرُكَ، وَلَا إِلٰهَ غَيْرُكَ" },
  { id: "d206", ch: 95, arabic: "بِسْمِ اللّٰهِ، الحَمْدُ لِلّٰهِ، سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، الحَمْدُ لِلّٰهِ، الحَمْدُ لِلّٰهِ، الحَمْدُ لِلّٰهِ، اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، سُبْحَانَكَ اللّٰهُمَّ إِنِّي ظَلَمْتُ نَفْسِي، فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ" },
  { id: "d207", ch: 96, arabic: "اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، اللّٰهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا البِرَّ وَالتَّقْوَى، وَمِنَ العَمَلِ مَا تَرْضَى، اللّٰهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ، اللّٰهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالخَلِيفَةُ فِي الأَهْلِ، اللّٰهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ المَنْظَرِ، وَسُوءِ المُنْقَلَبِ فِي المَالِ وَالأَهْلِ\nآيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ" },
  { id: "d208", ch: 97, arabic: "اللّٰهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ، وَرَبَّ الأَرْضِينَ السَّبْعِ وَمَا أَقْلَلْنَ، وَرَبَّ الشَّيَاطِينِ وَمَا أَضْلَلْنَ، وَرَبَّ الرِّيَاحِ وَمَا ذَرَيْنَ، أَسْأَلُكَ خَيْرَ هَذِهِ القَرْيَةِ وَخَيْرَ أَهْلِهَا، وَخَيْرَ مَا فِيهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ أَهْلِهَا، وَشَرِّ مَا فِيْهَا" },
  { id: "d209", ch: 98, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ المُلْكُ وَلَهُ الحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ حَيٌّ لَا يَمُوتُ، بِيَدِهِ الخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ" },
  { id: "d210", ch: 99, arabic: "بِسْمِ اللّٰهِ" },
  { id: "d211", ch: 100, arabic: "أَسْتَوْدِعُكُمُ اللّٰهَ الَّذِي لَا تَضِيعُ وَدَائِعُهُ" },
  { id: "d212", ch: 101, arabic: "أَسْتَودِعُ اللّٰهَ دِيْنَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ" },
  { id: "d213", ch: 101, arabic: "زَوَّدَكَ اللّٰهُ التَّقْوَى، وَغَفَرَ ذَنْبَكَ، ويَسَّرَ لَكَ الخَيْرَ حَيْثُمَا كُنْتَ" },
  { id: "d214", ch: 102, arabic: "اللّٰهُ أَكْبَرُ\nسُبْحَانَ اللّٰهِ" },
  { id: "d215", ch: 103, arabic: "سَمَّعَ سَامِعٌ بِحَمْدِ اللّٰهِ، وَحُسْنِ بَلائِهِ عَلَيْنَا، رَبَّنَا صَاحِبْنَا، وَأَفْضِلْ عَلَيْنَا، عَائِذًا بِاللّٰهِ مِنَ النَّارِ" },
  { id: "d216", ch: 104, arabic: "أَعُوْذُ بِكَلِمَاتِ اللّٰهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ" },
  { id: "d217", ch: 105, arabic: "اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ\nلَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ المُلْكُ وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ، آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ، صَدَقَ اللّٰهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الأَحْزَابَ وَحْدَهُ" },
  { id: "d218", ch: 106, arabic: "الحَمْدُ لِلّٰهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ\nالحَمْدُ لِلّٰهِ عَلَى كُلِّ حَالٍ" },
  { id: "d227", ch: 109, arabic: "وَعَلَيْكُمْ" },
  { id: "d228", ch: 110, arabic: "اللّٰهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ\nأَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ" },
  { id: "d229", ch: 111, arabic: "أَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ" },
  { id: "d230", ch: 112, arabic: "اللّٰهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ؛ فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ القِيَامَةِ" },
  { id: "d232", ch: 114, arabic: "اللّٰهُمَّ لَا تُؤَاخِذْنِي بِمَا يَقُولُونَ، وَاغْفِرْ لِي مَا لَا يَعْلَمُونَ [وَاجْعَلْنِي خَيْرًا مِمَّا يَظُنُّونَ]" },
  { id: "d233", ch: 115, arabic: "لَبَّيْكَ اللّٰهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيْكَ لَكَ لَبَّيْكَ، إِنَّ الحَمْدَ، وَالنِّعْمَةَ لَكَ وَالمُلْكَ، لَا شَرِيْكَ لَكَ" },
  { id: "d234", ch: 116, arabic: "اللّٰهُ أَكْبَرُ" },
  { id: "d235", ch: 117, arabic: "﴿...رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ {ayah:201}﴾" },
  { id: "d236", ch: 118, arabic: "﴿إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ﴾ أَبْدَأُ بِمَا بَدَأَ اللّٰهُ بِهِ\nلَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ المُلْكُ وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ، لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الأَحْزَابَ وَحْدَهُ" },
  { id: "d237", ch: 119, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ" },
  { id: "d238", ch: 120, arabic: "اللّٰهُ أَكْبَرُ\nلَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ\nلَا إِلٰهَ إِلَّا اللّٰهُ" },
  { id: "d239", ch: 121, arabic: "اللّٰهُ أَكْبَرُ" },
  { id: "d240", ch: 122, arabic: "سُبْحَانَ اللّٰهِ!" },
  { id: "d241", ch: 122, arabic: "اللّٰهُ أَكْبَرُ" },
  { id: "d243", ch: 124, arabic: "بِسْمِ اللّٰهِ\nأَعُوذُ بِاللّٰهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ" },
  { id: "d244", ch: 125, arabic: "اللّٰهُمَّ بَارِكْ لَهُ\nاللّٰهُمَّ بَارِكْ لَهَا" },
  { id: "d245", ch: 126, arabic: "لَا إِلٰهَ إلَّا اللّٰهُ!" },
  { id: "d246", ch: 127, arabic: "بِسْمِ اللّٰهِ وَاللّٰهُ أَكْبَرُ [اللّٰهُمَّ مِنْكَ وَلَكَ] اللّٰهُمَّ تَقَبَّلْ مِنِّي" },
  { id: "d247", ch: 128, arabic: "أَعُوذُ بِكَلِمَاتِ اللّٰهِ التَّامَّاتِ، الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ وَلَا فَاجِرٌ مِنْ شَرِّ مَا خَلَقَ، وَبَرَأَ وَذَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الأَرْضِ، وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ يَا رَحْمٰنُ" },
  { id: "d250", ch: 129, arabic: "أَسْتَغْفِرُ اللّٰهَ العَظِيمَ الَّذِي لَا إِلٰهَ إِلَّا هُوَ الحَيُّ القَيُّومُ وَأَتُوبُ إِلَيْهِ" },
  { id: "d254", ch: 130, arabic: "سُبْحَانَ اللّٰهِ وَبِحَمْدِهِ" },
  { id: "d255", ch: 130, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ المُلْكُ، وَلَهُ الحَمْدُ، وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ" },
  { id: "d256", ch: 130, arabic: "سُبْحَانَ اللّٰهِ وَبِحَمْدِهِ\nسُبْحَانَ اللّٰهِ العَظِيمِ" },
  { id: "d257", ch: 130, arabic: "سُبْحَانَ اللّٰهِ، وَالْحَمْدُ لِلّٰهِ، وَلَا إِلٰهَ إِلَّا اللّٰهُ، وَاللّٰهُ أَكْبَرُ" },
  { id: "d258", ch: 130, arabic: "سُبْحَانَ اللّٰهِ" },
  { id: "d259", ch: 130, arabic: "سُبْحَانَ اللّٰهِ العَظِيمِ وَبِحَمْدِهِ" },
  { id: "d260", ch: 130, arabic: "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ" },
  { id: "d261", ch: 130, arabic: "سُبْحَانَ اللّٰهِ\nالْحَمْدُ لِلّٰهِ\nلَا إِلٰهَ إِلَّا اللّٰهُ\nاللّٰهُ أَكْبَرُ" },
  { id: "d262", ch: 130, arabic: "لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، اللّٰهُ أَكْبَرُ كَبِيرًا، وَالحَمْدُ لِلّٰهِ كَثِيرًا، سُبْحَانَ اللّٰهِ رَبِّ العَالَمِينَ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ العَزِيزِ الحَكِيمِ\nاللّٰهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَارْزُقْنِي" },
  { id: "d263", ch: 130, arabic: "اللّٰهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي، وَارْزُقْنِي" },
  { id: "d264", ch: 130, arabic: "الحَمْدُ لِلّٰهِ\nلَا إِلٰهَ إِلَّا اللّٰهُ" },
  { id: "d265", ch: 130, arabic: "سُبْحَانَ اللّٰهِ\nالْحَمْدُ لِلّٰهِ\nلَا إِلٰهَ إِلَّا اللّٰهُ\nاللّٰهُ أَكْبَرُ\nلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ" },
];

